if (!isset($conn)) require_once 'includes/db.php';
if (!function_exists('slugify_category')) {
  function slugify_category(string $n): string {
    return trim(preg_replace('/[^a-z0-9]+/','-',strtolower(trim($n))),'-');
  }
}
